'use strict';

/**
 * Стрим для yandex-logger, позволяющий логировать в Qloud-совместимом формате.
 *
 * @param {YandexLoggerQloudStreamConfig} config
 * @returns {Writable}
 */
module.exports = config => {
    config = config || {};

    return require('./deploy')(config);
};

/**
 * @typedef {Object} YandexLoggerQloudStreamConfig
 * @property {String} [stream] - Writable stream, например, process.stdout
 * @property {String[]} [excludeFields] - Поля, которые нужно исключить из логов
 */
